contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt to withdraw `amount` from c as msg.sender == this contract
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // record observable balances before the call
        uint256 beforeContractEth = address(c).balance;
        uint256 beforeThisEth = address(this).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterContractEth = address(c).balance;
        uint256 afterThisEth = address(this).balance;

        // General rule: if withdraw did not revert then exactly `amount` Ether moved from c to this contract
        assert(reverted || (beforeContractEth == afterContractEth + amount && afterThisEth == beforeThisEth + amount));
    }

    // Allow receiving Ether from c
    receive() external payable {}
}

